  "„Alle erinnern“ in den Beiträgen wartet so viele Tage nach der Fälligkeit und kann einen Zusatztext anhängen.": "«Recordar a todos» en las cuotas espera estos días tras el vencimiento y puede añadir un texto adicional.",
  "„Anlage & Material“ ist im Verein nicht aktiviert.": "«Instalaciones y material» no está activado en el club.",
  "„Automatisch zugesagt“ ist empfohlen; bei aktiver Antwort gilt jede Person als offen, bis sie antwortet. Änderungen gelten für neue Termine.": "Se recomienda «Confirmado automáticamente»; con respuesta activa, cada persona figura como pendiente hasta que responde. Los cambios valen para eventos nuevos.",
  "„Fällige Beiträge anlegen“ erzeugt für alle zugeordneten Mitglieder die Forderungen, die bis heute fällig sind – nie doppelt.": "«Crear cuotas vencidas» genera para todos los socios asignados los cobros vencidos hasta hoy, nunca duplicados.",
  "„Ich → Einstellungen → Einladen“ oder im Team „Person zur Mannschaft einladen“: persönlich per E-Mail oder als Mannschafts-Link bzw. QR-Code zum Selbstregistrieren. Bei Links gibst du neue Anfragen frei, bevor jemand die App nutzen kann.": "«Yo → Ajustes → Invitar» o, en Equipo, «Invitar a una persona al equipo»: de forma personal por correo electrónico o como enlace del equipo o código QR para registrarse por cuenta propia. En los enlaces, apruebas las nuevas solicitudes antes de que alguien pueda usar la app.",
  "„Mannschaft bearbeiten → Spielplan importieren“: CSV-Datei aus dem DFBnet wählen, Vorschau prüfen (neu, geändert, unverändert, übersprungen) und übernehmen. Die Mannschaft bekommt eine Sammelmeldung. Ein erneuter Import aktualisiert Verlegungen, statt Spiele doppelt anzulegen. Innerhalb von 24 Stunden kannst du den Import rückgängig machen.": "«Editar equipo → Importar calendario»: elige el archivo CSV de DFBnet, revisa la vista previa (nuevo, modificado, sin cambios, omitido) y aplícalo. El equipo recibe un aviso conjunto. Una nueva importación actualiza los aplazamientos en lugar de duplicar partidos. Puedes deshacer la importación durante 24 horas.",
  "„Team → Kader → Mannschaft bearbeiten“: Spieler aus der Vereinsliste hinzufügen oder aus dem Kader nehmen, Funktion (Spieler, Co-Trainer, Betreuer) und Rückennummer ändern, den Kassenwart bestimmen. Unten stellst du ein, wie viele Minuten vor Spielen und Trainings ihr euch trefft, den Standard-Treffpunkt und die Schreibweisen eurer Mannschaft im DFBnet. Co-Trainer haben dieselben Rechte wie der Trainer.": "«Equipo → Plantilla → Editar equipo»: añade jugadores de la lista del club o quítalos de la plantilla, cambia la función (jugador, entrenador asistente, delegado) y el dorsal, y designa al tesorero. Abajo configuras cuántos minutos antes de los partidos y entrenamientos quedáis, el punto de encuentro habitual y cómo aparece vuestro equipo en DFBnet. Los entrenadores asistentes tienen los mismos derechos que el entrenador.",
  "„Team → Kasse → Kassenverwaltung“. Dort liegen als Kacheln: Einnahme/Ausgabe, Einzahlungen, Strafe vergeben, Getränke-Strichliste, Umlage, Beiträge, Buchungen & Storno, Kassenwart, Bezahlinfos und Kassenprüfung.": "«Equipo → Caja → Gestión de caja». Allí encontrarás estos mosaicos: ingreso/gasto, pagos recibidos, poner multa, lista de bebidas, derrama, cuotas, movimientos y anulaciones, tesorero, datos de pago y auditoría de caja.",
  "„Team → Termin anlegen“: Training, Spiel oder Mannschaftstermin. Spiele bekommen die Art Liga, Pokal oder Testspiel. Zum Wiederholen wählst du „Wöchentlich bis …“ und das Enddatum (bis zu etwa einem Jahr). Die Treffzeit berechnet die App aus den Regeln deiner Mannschaft; im einzelnen Termin kannst du sie überschreiben. Im Termin änderst du mit „Termin bearbeiten“ einzelne Termine oder „diesen und folgende“. Mit „Termin absagen“ wird die Mannschaft sofort benachrichtigt.": "«Equipo → Crear evento»: entrenamiento, partido o evento del equipo. Los partidos tienen el tipo liga, copa o amistoso. Para repetirlo eliges «Semanalmente hasta …» y la fecha final (hasta aproximadamente un año). La app calcula la hora de encuentro según las reglas de tu equipo; en cada evento puedes modificarla. Con «Editar evento» cambias eventos individuales o «este y los siguientes». Con «Cancelar evento» se avisa al equipo de inmediato.",
  "„Unsicher“ als Antwort erlauben": "Permitir «Dudoso» como respuesta",
