  "Auch Dubletten werden als neue Einträge angelegt.": "Los duplicados también se crean como entradas nuevas.",
  "auch mehrere auf einmal": "también varios a la vez",
  "Auch Mitspieler sehen den Grund einer Absage oder Abwesenheit (z. B. verletzt, krank).": "Los compañeros también ven el motivo de una cancelación o ausencia (p. ej., lesión, enfermedad).",
  "Auch ohne Werbung bleibt der Sponsor in der Übersicht sichtbar.": "Aunque no haya publicidad, el patrocinador sigue visible en el resumen.",
  "Audit-Log einsehen": "Ver registro de auditoría",
  "Auf der letzten Seite findest du die passenden Schaltflächen.": "En la última página encontrarás los botones correspondientes.",
  "Auf der Startseite und unter „Verein → News“. Dringende Meldungen stehen oben und erreichen dich auch per Push. Mit „Gefällt mir“ und Kommentaren kannst du reagieren.": "En Inicio y en «Club → Noticias». Los avisos urgentes aparecen arriba y te llegan también por notificación push. Puedes reaccionar con «Me gusta» y comentarios.",
  "Auf die Forderung wurde schon gezahlt. Storniere zuerst die Buchung im Kassenbuch.": "Este cobro ya tiene pagos. Anula primero el movimiento en el libro de caja.",
  "Auf jeder Unterseite siehst du oben deinen Weg, zum Beispiel „Team › Kasse › Strafenkatalog“. Tippe auf eine frühere Stufe, um dorthin zurückzugehen, oder auf den runden Pfeil für einen Schritt zurück. Bei langen Wegen steht „…“ für die ausgelassenen Stufen; ein Tipp zeigt sie als Liste. Die untere Leiste bleibt sichtbar, der aktuelle Bereich ist markiert.": "En cada subpágina ves arriba tu ruta, por ejemplo «Equipo › Caja › Catálogo de multas». Toca un nivel anterior para volver a él, o la flecha redonda para retroceder un paso. En rutas largas, «…» representa los niveles omitidos; al tocarlo se muestran como lista. La barra inferior permanece visible y el área actual está marcada.",
  "Auf Konto": "A la cuenta",
  "auf später verschoben": "pospuesto",
