  "Aus Datenschutzgründen siehst du nur Zahlen. Den Trainer der Mannschaft kannst du über „Ansprechpartner“ erreichen.": "Por protección de datos solo ves cifras. Puedes contactar con el entrenador del equipo a través de «Persona de contacto».",
