  "Aus diesen Regeln berechnet die App bei jedem neuen Spiel und Training die Treffzeit. Beim einzelnen Termin kannst du sie jederzeit überschreiben. Leer lassen = kein automatisches Treffen.": "Con estas reglas la app calcula la hora de encuentro de cada partido y entrenamiento nuevos. En cada evento puedes modificarla en cualquier momento. Vacío = sin quedada automática.",
  "Aus einer Excel- oder CSV-Datei. Du siehst zuerst eine Vorschau – übernommen wird erst nach deiner Bestätigung.": "Desde un archivo Excel o CSV. Primero ves una vista previa; no se aplica hasta que lo confirmes.",
