  "Aus: Jede Person sieht nur die eigenen Beträge. Kassenstand, Einnahmen und Ausgaben sieht immer die ganze Mannschaft.": "Desactivado: cada persona solo ve sus propios importes. El saldo de caja, los ingresos y los gastos los ve siempre todo el equipo.",
