  "Beginn": "Inicio",
  "Beginn „{0}“ ist ungültig.": "El inicio «{0}» no es válido.",
  "Beginn im {0}": "Inicio en {0}",
  "Beginnt am {0}. Kader planst du unter Verwaltung → Mitglieder: Mannschaften der neuen Saison sind dort mit „(Saison {1})“ gekennzeichnet.": "Empieza el {0}. Las plantillas se planifican en Administración → Socios: los equipos de la nueva temporada llevan allí la marca «(temporada {1})».",
  "Begründung": "Motivo",
  "Begründung (bei Ablehnung)": "Motivo (en caso de rechazo)",
  "Begründung für das Storno": "Motivo de la anulación",
  "Begünstigter Zweck": "Fin beneficiado",
  "Bei Auswärtsspielen und Turnieren gibt es im Termin den Bereich „Fahrgemeinschaften“. Tippe auf „Ich fahre“ und gib die freien Plätze an, oder wähle bei einem Auto „Mitfahren“. Wer keine Mitfahrt hat, tippt auf „Mitfahrt suchen“. Eltern buchen für ihre Kinder.": "En los partidos fuera y torneos, el evento incluye el apartado «Viajes compartidos». Toca «Yo conduzco» e indica las plazas libres, o elige «Ir en este coche» en un coche. Quien no tenga viaje toca «Buscar viaje». Los padres reservan para sus hijos.",
  "Bei der Anmeldung schicken wir dir einen 6-stelligen Code per E-Mail (10 Minuten gültig, nur einmal nutzbar). Sicherer ist eine Authenticator-App – der E-Mail-Code ist die einfachere Alternative.": "Al iniciar sesión te enviamos un código de 6 dígitos por correo electrónico (válido 10 minutos, de un solo uso). Una app de autenticación es más segura; el código por correo es la alternativa más sencilla.",
  "Bei dir": "Contigo",
  "Bei Dubletten": "En caso de duplicados",
  "Bei einer Absage ist ein Grund Pflicht": "Al cancelar es obligatorio indicar un motivo",
  "Bei Spielen fehlt der Gegner.": "En los partidos falta el rival.",
  "bei Spielen Pflicht": "obligatorio en partidos",
  "Bei Terminen fehlt der Titel.": "En los eventos falta el título.",
  "bei Terminen Pflicht, sonst automatisch": "obligatorio en eventos; si no, automático",
  "Bei Terminen siehst du die Antwort für jede Person. Zu- und Absagen gelten je Kind.": "En los eventos ves la respuesta de cada persona. Las confirmaciones y cancelaciones valen por cada hijo.",
  "Bei Vereinsveranstaltungen (z. B. Jahreshauptversammlung, Turnier) kannst du Zusagen, Absagen oder „Unsicher“ wählen – ohne Begründung. Zusätzlich gibt es oft „Helfer gesucht“: Trage dich in eine Schicht ein.": "En los actos del club (p. ej., asamblea general, torneo) puedes elegir confirmar, cancelar o «Dudoso», sin necesidad de motivo. Además suele haber «Se buscan ayudantes»: apúntate a un turno.",
  "beidfüßig": "ambidiestro",
  "Beidfüßig": "Ambidiestro",
  "Beim Austritt werden alle Mannschaftszuordnungen beendet, Rollen entzogen und der App-Zugang gesperrt. Die Daten bleiben für die Vereinsunterlagen erhalten.": "Al darse de baja, se finalizan todas las asignaciones a equipos, se retiran los roles y se bloquea el acceso a la app. Los datos se conservan para la documentación del club.",
  "Beim Buchen einer Einnahme wählst du den Sponsor aus (Verein → Sponsoren).": "Al registrar un ingreso eliges el patrocinador (Club → Patrocinadores).",
  "Beim Eigentor des Gegners gibt es keinen Torschützen.": "En un gol en propia puerta del rival no hay goleador.",
  "Beim Kassenwart oder Trainerteam": "Con el tesorero o el cuerpo técnico",
  "Beim Löschen werden die automatischen Absagen zurückgenommen. Bei Mannschaften mit aktiver Zu-/Absage ist die Rückmeldung danach wieder offen.": "Al eliminar, se revocan las cancelaciones automáticas. En los equipos con confirmación/cancelación activa, la respuesta vuelve a quedar pendiente.",
  "Beim Planen einer Veranstaltung wählst du oben die Gruppe („Ganzer Verein“, eine Abteilung …). Mit „Mannschaften oder Personen auswählen“ lädst du gezielt ein: Setze im Fenster Häkchen bei Mannschaften oder suche Personen. Die Auswahl erscheint als Chips; mit „×“ nimmst du jemanden wieder heraus. Nur die Eingeladenen werden benachrichtigt. Einzelne Personen darfst du nur mit dem Recht für die Mitgliederliste einladen.": "Al planificar un acto eliges arriba el grupo («Todo el club», una sección…). Con «Elegir equipos o personas» invitas de forma selectiva: marca equipos en la ventana o busca personas. La selección aparece como etiquetas; con «×» quitas a alguien. Solo se avisa a los invitados. Solo puedes invitar a personas concretas si tienes el derecho sobre la lista de socios.",
  "Beim Start und nach einer Minute im Hintergrund fragt die App nach Face ID, Fingerabdruck oder dem Gerätecode. Die Einstellung gilt nur auf diesem Gerät.": "Al abrir y tras un minuto en segundo plano, la app pide Face ID, huella o el código del dispositivo. El ajuste solo vale en este dispositivo.",
