  "Beispieltext: Die Haftung richtet sich nach den gesetzlichen Vorschriften. Details folgen in der endgültigen Fassung.": "Texto de ejemplo: la responsabilidad se rige por las disposiciones legales. Los detalles se incluirán en la versión definitiva.",
