  "Buchen": "Registrar",
  "Buchen, Strafen vergeben, Einzahlungen erfassen und den Strafenkatalog pflegen – gemeinsam mit dem Kassenwart. Alles Weitere steht im Abschnitt „Kassenverwaltung“.": "Registrar movimientos, poner multas, anotar pagos recibidos y mantener el catálogo de multas, junto con el tesorero. Lo demás está en el apartado «Gestión de caja».",
