  "Buchungen dürfen nur Kassenverantwortliche erfassen.": "Solo los responsables de la caja pueden registrar movimientos.",
  "Buchungen werden nie gelöscht, sondern storniert: „Buchungen & Storno“, Buchung antippen, optional Grund eintragen. Die Buchung bleibt durchgestrichen sichtbar und steht im Änderungsprotokoll. Zum Korrigieren neu buchen.": "Los movimientos nunca se eliminan, se anulan: «Movimientos y anulaciones», toca el movimiento e indica opcionalmente un motivo. El movimiento permanece visible tachado y consta en el registro de cambios. Para corregir, registra uno nuevo.",
