  "Das Kürzel „{0}“ ist in dieser Saison vergeben.": "La abreviatura «{0}» ya está en uso esta temporada.",
  "Das Kürzel (2 bis 4 Zeichen, z. B. „SGW“) steht groß im Plakat der Startseite und ersetzt das Wappen, solange kein Logo hochgeladen ist. Die Vereinsadministration ändert es unter „Verwaltung → Verein & Design“, mit Vorschau. Die Vibration bei Auswahl und Bestätigung schaltest du auf dem Handy unter „Ich → Konto & Einstellungen → Vibration“ aus; bei eingestellter „Bewegung reduzieren“ des Geräts bleiben auch die Animationen aus.": "La abreviatura (de 2 a 4 caracteres, p. ej., «SGW») aparece en grande en el cartel de Inicio y sustituye al escudo mientras no se haya subido un logotipo. La administración del club la cambia en «Administración → Club y diseño», con vista previa. La vibración al seleccionar y confirmar la desactivas en el móvil en «Yo → Cuenta y ajustes → Vibración»; si el dispositivo tiene activada la opción «Reducir movimiento», tampoco se muestran las animaciones.",
  "Das Kürzel besteht aus 2 bis 4 Buchstaben oder Ziffern.": "La abreviatura consta de 2 a 4 letras o cifras.",
  "Das Kürzel steht groß im Plakat auf der Startseite und ersetzt das Wappen, solange kein Logo hochgeladen ist.": "La abreviatura aparece en grande en el cartel de Inicio y sustituye al escudo mientras no se haya subido un logotipo.",
  "Das laufende Jahr kann erst nach seinem Ende abgeschlossen werden.": "El año en curso solo se puede cerrar una vez terminado.",
  "Das Logo erscheint oben in der App bei allen Mitgliedern.": "El logotipo aparece arriba en la app para todos los socios.",
