  "Das sind alle Termine.": "Estos son todos los eventos.",
  "Das sind optionale Funktionen, die dein Verein einschalten kann: Fundbüro & Marktplatz für Gesuchtes und Gefundenes, ein kleines Forum für wenige Themen und Vereinswissen mit Artikeln wie „Wo gibt es den Schlüssel?“. Sie erscheinen nur, wenn sie aktiv sind.": "Son funciones opcionales que tu club puede activar: objetos perdidos y mercadillo para lo buscado y lo encontrado, un pequeño foro para pocos temas y conocimiento del club con artículos como «¿Dónde está la llave?». Solo aparecen si están activas.",
