  "Das Trainerteam sieht Grund und Freitext immer, Eltern die Gründe ihres Kindes. Ob auch die Mitspieler die Gründe sehen, stellt das Trainerteam in „Mannschaft bearbeiten“ ein („Abwesenheitsgründe für die Mannschaft sichtbar“, Standard aus).": "El cuerpo técnico ve siempre el motivo y el texto libre; los padres, los motivos de su hijo. Si los compañeros también ven los motivos, lo configura el cuerpo técnico en «Editar equipo» («Motivos de ausencia visibles para el equipo», desactivado por defecto).",
  "Das Trainerteam von {0} prüft deine Anfrage. Sobald sie freigegeben ist, bekommst du eine E-Mail und kannst dich anmelden.": "El cuerpo técnico de {0} está revisando tu solicitud. En cuanto se apruebe, recibirás un correo electrónico y podrás iniciar sesión.",
