  "Der Verein kann mehrere Kassen führen, z. B. eine Jugendkasse. Unter „Admin-Verwaltung → Verein → Abteilungen“ legst du Abteilungen an (z. B. Senioren, Frauen, Jugend); danach fragt die App, ob die Abteilung eine eigene Kasse bekommen soll. Unter „Kassen“ legst du Kassen an, ordnest sie einer oder mehreren Abteilungen zu und bestimmst genau eine Hauptkasse. Ohne eigene Kasse laufen die Buchungen einer Abteilung über die Hauptkasse. Jede Kasse hat eigene Konten und Beiträge; in der Vereinskasse wechselst du oben zwischen „Alle“ und einer einzelnen Kasse. Kassen werden nie gelöscht, nur stillgelegt. Eine Umbuchung zwischen Konten verschiedener Kassen wird in beiden Kassen gebucht, ein Storno wirkt in beiden. Die Rolle Kassenwart (Verein) kann für den ganzen Verein oder nur für eine Abteilung vergeben werden und gilt dann nur für deren Kassen.": "El club puede llevar varias cajas, p. ej., una caja juvenil. En «Administración → Club → Secciones» creas secciones (p. ej., Senior, Femenino, Juvenil); después la app pregunta si la sección debe tener caja propia. En «Cajas» creas cajas, las asignas a una o varias secciones y defines exactamente una caja principal. Sin caja propia, los movimientos de una sección pasan por la caja principal. Cada caja tiene sus propias cuentas y cuotas; en la caja del club cambias arriba entre «Todas» y una caja concreta. Las cajas nunca se eliminan, solo se dan de baja. Un traspaso entre cuentas de cajas distintas se registra en ambas cajas, y una anulación afecta a ambas. El rol de tesorero (club) puede asignarse a todo el club o solo a una sección, y entonces vale solo para las cajas de esta.",
  "Der Verein verlangt für deine Rolle die 2-Faktor-Anmeldung.": "El club exige la autenticación en dos pasos para tu rol.",
  "Der Verein verlangt für die Verwaltung die 2-Faktor-Anmeldung. Bitte unter „Konto & Sicherheit“ einrichten.": "El club exige la autenticación en dos pasos para la administración. Configúrala en «Cuenta y seguridad».",
  "Der Verein verlangt sie für deine Verwaltungsrechte. Bis dahin ist die Verwaltung gesperrt.": "El club la exige para tus derechos de administración. Hasta entonces la administración está bloqueada.",
  "Der Vermerk": "La nota",
  "Der Vermerk wird entfernt.": "La nota se eliminará.",
  "Der Verwendungszweck fehlt.": "Falta el concepto.",
  "Der volle Name steht auf Dokumenten, der Kurzname in der Kopfzeile und auf dem Wappen.": "El nombre completo figura en los documentos; el nombre corto, en la cabecera y en el escudo.",
  "Der Vorstand sieht – wenn der Verein es in „Einsicht“ freigibt – unter „Verein → Vereinsleben → Kassenübersicht“ eine reine Anzeige: Kassenstand gesamt, Einnahmen und Ausgaben, die einzelnen Kassen und die Beitragsquote. Buchungen, Belege und Funktionen gibt es dort nicht; die Vereinskasse selbst führen Kassenwart und Kassenprüfer.": "Si el club lo habilita en «Consulta», la junta directiva ve en «Club → Vida del club → Resumen de caja» una vista de solo lectura: saldo total de caja, ingresos y gastos, cada caja y la tasa de cuotas pagadas. Allí no hay movimientos, justificantes ni funciones; la caja del club la llevan el tesorero y los auditores de caja.",
  "Der Vorstand sieht auch Kassenbuch und Belege (ohne zu buchen)": "La junta directiva ve también el libro de caja y los justificantes (sin poder registrar)",
  "Der Vorstand sieht Kontostände und Summen, aber keine einzelnen Buchungen": "La junta directiva ve saldos y totales, pero no los movimientos individuales",
  "Der Wert ist ungültig.": "El valor no es válido.",
  "Der Zeitraum darf höchstens 120 Tage umfassen.": "El periodo no puede superar los 120 días.",
