  "Der Zuschuss steht als Ausgabe im Kassenbuch und zugleich als Einnahme in der Mannschaftskasse. Danach kann er nicht mehr einzeln storniert werden.": "La subvención figura como gasto en el libro de caja y a la vez como ingreso en la caja del equipo. Después ya no se puede anular por separado.",
