  "Die Einstellung gilt für alle Mannschaften der Abteilung. Ist ein Modul hier aus, kann es keine Mannschaft darin einschalten. „Wie Verein“ übernimmt die Vereinseinstellung.": "El ajuste vale para todos los equipos de la sección. Si un módulo está desactivado aquí, ningún equipo puede activarlo. «Como el club» adopta el ajuste del club.",
