  "Die Frist für Korrekturen ist abgelaufen – nur der Admin kann die Anwesenheit noch ändern.": "El plazo para correcciones ha terminado: solo el administrador puede cambiar la asistencia.",
  "Die Frist für Zu- und Absagen ist abgelaufen. Bitte wende dich an dein Trainerteam.": "El plazo para confirmar o cancelar ha terminado. Dirígete a tu cuerpo técnico.",
  "Die Frist ist am {0}, {1} Uhr abgelaufen. Bei Änderungen wende dich an dein Trainerteam.": "El plazo terminó el {0} a las {1} h. Para cambios, dirígete a tu cuerpo técnico.",
