  "Die Hauptkasse kann nicht stillgelegt werden. Lege zuerst eine andere Kasse als Hauptkasse fest.": "La caja principal no se puede dar de baja. Define primero otra caja como principal.",
  "Die Hauptkasse nimmt Buchungen ohne Abteilungsbezug auf und kann nicht stillgelegt werden. Lege eine andere Kasse als Hauptkasse fest, um zu wechseln.": "La caja principal recoge los movimientos sin sección asociada y no se puede dar de baja. Define otra caja como principal para cambiar.",
