  "Die Kaderliste ist für dich nicht freigegeben.": "La lista de la plantilla no está habilitada para ti.",
  "Die Kasse": "La caja",
  "Die Kasse bestätigt den Eingang – erst dann ist dein Konto ausgeglichen.": "La caja confirma la recepción; solo entonces tu cuenta queda saldada.",
  "Die Kasse ist stillgelegt.": "La caja está dada de baja.",
  "Die Kasse konnte nicht vollständig eingerichtet werden.": "No se pudo configurar la caja por completo.",
  "Die Kassenprüfung machen Kassenprüfer.": "La auditoría de caja la hacen los auditores de caja.",
  "Die Kassenprüfung machen Kassenprüfer. Hier siehst du die abgegebenen Prüfberichte.": "La auditoría de caja la hacen los auditores de caja. Aquí ves los informes de auditoría entregados.",
  "Die Kassenstatistik sieht die Mannschaft.": "Las estadísticas de caja las ve el equipo.",
  "Die Kassenverwaltung ist für Kassenwart und Trainerteam.": "La gestión de caja es para el tesorero y el cuerpo técnico.",
  "Die Kategorie": "La categoría",
  "Die Kategorie „{0}“ gilt für Ausgaben.": "La categoría «{0}» es para gastos.",
  "Die Kategorie „{0}“ gilt für Einnahmen.": "La categoría «{0}» es para ingresos.",
  "Die Kategorie ist archiviert.": "La categoría está archivada.",
  "Die Kennzahl zeigt auf einen Blick, was dort los ist: bei Terminen und Veranstaltungen das Datum des nächsten (TT.MM.), beim Kader die Zahl der Spieler, bei der Statistik die Bilanz (Siege-Remis-Niederlagen), bei der Kasse den Kassenstand, bei Aufgaben und Umfragen die offenen, bei News, Dokumenten und Wissen die neuen, beim Spielplan die Spiele der Woche, bei Helfern die freien Plätze. Orange heißt: Hier wartet etwas auf dich. Kacheln ohne sinnvolle Zahl haben keine Kennzahl.": "El indicador muestra de un vistazo qué ocurre allí: en eventos y actos, la fecha del próximo (DD.MM.); en la plantilla, el número de jugadores; en las estadísticas, el balance (victorias-empates-derrotas); en la caja, el saldo; en tareas y encuestas, las pendientes; en noticias, documentos y conocimiento, las nuevas; en el calendario, los partidos de la semana; en ayudantes, las plazas libres. Naranja significa que algo te espera. Los mosaicos sin una cifra con sentido no tienen indicador.",
  "Die kleine Zeile unter dem Namen einer Kachel zeigt, was für dich gerade wichtig ist, z. B. „Du hast 12,50 € offen“, „Antwort fehlt“ oder „2 zur Freigabe“. Die Farbe verstärkt den Text: Orange heißt, es gibt etwas zu tun. Was du nicht sehen darfst, wird nicht angezeigt.": "La línea pequeña bajo el nombre de un mosaico muestra lo que ahora es importante para ti, p. ej., «Tienes 12,50 € pendientes», «Falta respuesta» o «2 para aprobar». El color refuerza el texto: naranja significa que hay algo que hacer. Lo que no puedes ver no se muestra.",
  "Die Kostenstelle": "El centro de coste",
  "Die Lesebestätigung sehen Verfasser und Freigebende.": "La confirmación de lectura la ven el autor y quienes aprueban.",
