  "Die Vereinseinstellungen ändert die Vereinsadministration.": "Los ajustes del club los cambia la administración del club.",
  "Die Vereinskasse einrichten": "Configurar la caja del club",
  "Die Vereinskasse führt der Kassenwart (Verein).": "La caja del club la lleva el tesorero (club).",
  "Die Vereinskasse führt nur die Kassenführung.": "La caja del club solo la lleva la gestión de caja.",
  "Die Vereinskasse ist nicht aktiviert.": "La caja del club no está activada.",
  "Die Vereinskasse ist von den Mannschaftskassen getrennt und liegt unter „Verein → Vereinskasse“ (wenn das Modul aktiv ist). Der Kassenwart (Verein) legt Konten mit Anfangsbestand an, bucht Einnahmen und Ausgaben mit Kategorie, optionaler Kostenstelle, Belegnummer und Belegfoto und bucht um zwischen Konten. Buchungen werden nie gelöscht, sondern mit Begründung storniert. Die Kategorien gehören zu den vier steuerlichen Bereichen (ideell, Vermögensverwaltung, Zweckbetrieb, wirtschaftlicher Geschäftsbetrieb). Kassenprüfer lesen alles, buchen aber nicht. Wer außerdem einsehen darf (z. B. der Vorstand), stellt die Vereinsadministration unter „Einrichtung“ ein.": "La caja del club está separada de las cajas de los equipos y se encuentra en «Club → Caja del club» (si el módulo está activo). El tesorero (club) crea cuentas con saldo inicial, registra ingresos y gastos con categoría, centro de coste opcional, número de justificante y foto del justificante, y hace traspasos entre cuentas. Los movimientos nunca se eliminan, se anulan con un motivo. Las categorías pertenecen a las cuatro áreas fiscales (ideal, administración del patrimonio, actividad de fin social, actividad económica). Los auditores de caja lo leen todo, pero no registran. Quién más puede consultarla (p. ej., la junta directiva) lo define la administración del club en «Configuración».",
  "Die Vereinskasse sehen nur Kassenführung und Prüfer.": "La caja del club solo la ven la gestión de caja y los auditores.",
  "Die Verwaltung ist für Vorstand, Leitung und Administration.": "La administración es para la junta directiva, la dirección y la administración.",
  "Die Vorlage ist noch nicht freigegeben. Sie muss zuerst rechtlich bzw. steuerlich geprüft werden.": "La plantilla aún no está habilitada. Primero debe revisarse legal o fiscalmente.",
  "Die Vorlage mit Beispielzeile und Spaltenerklärung lädst du in der Web-Verwaltung herunter.": "La plantilla con fila de ejemplo y explicación de columnas la descargas en la administración web.",
  "Die Vorlage muss zuerst rechtlich bzw. steuerlich geprüft und von der Administration freigegeben werden.": "La plantilla debe revisarse primero legal o fiscalmente y ser habilitada por la administración.",
  "Die Vorlage schaltet passende Funktionen für die Mannschaft ein.": "La plantilla activa las funciones adecuadas para el equipo.",
