  "Du kannst nur Rechte vergeben oder entziehen, die du selbst hast.": "Solo puedes asignar o retirar derechos que tú mismo tienes.",
  "Du kannst nur Rechte vergeben, die du selbst hast.": "Solo puedes asignar derechos que tú mismo tienes.",
  "Du kannst nur Spieler deiner eigenen Mannschaften abstellen.": "Solo puedes ceder jugadores de tus propios equipos.",
  "Du kannst nur Zahlungen für dich oder deine Kinder melden.": "Solo puedes comunicar pagos propios o de tus hijos.",
  "Du kannst Spieler abstellen": "Puedes ceder jugadores",
  "Du kannst weitere Anlagen ergänzen und alles später in der Verwaltung ändern.": "Puedes añadir más instalaciones y cambiarlo todo después en la administración.",
  "Du siehst den Vereinsüberblick, alle Vereinstermine und News, kannst bei Veranstaltungen zu- oder absagen und dich als Helfer eintragen. Eigene News kannst du schreiben; sie werden nach Freigabe durch den Vorstand veröffentlicht.": "Ves el resumen del club, todos los eventos y noticias del club, puedes confirmar o cancelar en los actos y apuntarte como ayudante. Puedes escribir tus propias noticias; se publican tras la aprobación de la junta directiva.",
  "Du siehst die Vereinskasse nur als Auswertung, nicht einzelne Buchungen.": "Ves la caja del club solo como informe, no los movimientos individuales.",
