  "Ein abgeschlossenes Jahr öffnet nur die Administration.": "Un año cerrado solo lo reabre la administración.",
  "Ein ausgeblendeter Beitrag lässt sich nicht ändern.": "Una publicación oculta no se puede modificar.",
  "Ein erledigter Aushang lässt sich nicht ändern.": "Un anuncio resuelto no se puede modificar.",
  "Ein geänderter Betrag gilt für künftige Beiträge; bereits erzeugte Forderungen bleiben unverändert. Der Rhythmus lässt sich nicht ändern.": "Un importe modificado vale para cuotas futuras; los cobros ya generados no cambian. La periodicidad no se puede cambiar.",
  "Ein Getränk mehr": "Una bebida más",
  "Ein Getränk weniger": "Una bebida menos",
  "Ein Jahr kann erst nach seinem Ende abgeschlossen werden.": "Un año solo se puede cerrar una vez terminado.",
  "Ein Kind kann nicht sein eigener Elternteil sein.": "Un hijo no puede ser su propio padre o madre.",
  "Ein kurzer Willkommenstext erscheint im Team-Tab – zum Beispiel zu Kleidung, Treffpunkten und Regeln.": "Un breve texto de bienvenida aparece en la pestaña Equipo, por ejemplo sobre ropa, puntos de encuentro y normas.",
  "Ein Mannschafts-Link (oder QR-Code als Aushang) lässt neue Spieler und Eltern eine Beitrittsanfrage stellen. Du gibst jede Anfrage frei. Ein neuer Link macht den alten ungültig.": "Con un enlace del equipo (o un código QR como anuncio), los nuevos jugadores y padres pueden enviar una solicitud de ingreso. Tú apruebas cada solicitud. Un enlace nuevo invalida el anterior.",
  "ein Platz bleibt frei": "queda una plaza libre",
  "Ein Platz der Formation ist doppelt besetzt.": "Una posición de la formación está ocupada dos veces.",
  "Ein Spieler steht doppelt in der Aufstellung.": "Un jugador aparece dos veces en la alineación.",
  "Ein Sponsor passt nur zu einer Einnahme.": "Un patrocinador solo corresponde a un ingreso.",
  "Ein Team": "Un equipo",
  "Ein Verein mit nur einer Administration ist ein Risiko: Fällt die Person aus, kommt niemand mehr an die Einstellungen. Bestimme eine zweite Person mit denselben Rechten.": "Un club con un solo administrador es un riesgo: si esa persona no está, nadie accede a los ajustes. Nombra a una segunda persona con los mismos derechos.",
  "Ein zusätzlicher Schutz: Nach dem Passwort fragt die App einen Code ab – aus einer Authenticator-App oder per E-Mail (6 Stellen, 10 Minuten gültig, nur einmal nutzbar). Du richtest ihn unter „Ich → Konto & Einstellungen“ ein. Pflicht ist er nur für das Administrationskonto, wenn der Verein es verlangt.": "Una protección adicional: tras la contraseña, la app pide un código, de una app de autenticación o por correo electrónico (6 dígitos, válido 10 minutos, de un solo uso). Lo configuras en «Yo → Cuenta y ajustes». Solo es obligatorio para la cuenta de administración si el club lo exige.",
  "eindeutig im Verein": "único en el club",
  "Eine abgesagte Veranstaltung lässt sich nicht ändern.": "Un acto cancelado no se puede modificar.",
  "Eine Abwesenheit darf höchstens ein Jahr dauern.": "Una ausencia no puede durar más de un año.",
