  "Eine Mannschaft ist eine Gruppe mit eigenem Kader, eigenen Terminen und eigenen Regeln – zum Beispiel „B-Jugend“ oder „1. Herren“. Alles lässt sich später ändern.": "Un equipo es un grupo con su propia plantilla, eventos y reglas, por ejemplo «Juvenil B» o «Primer equipo masculino». Todo se puede cambiar después.",
