  "Einzeln unter „Mitglieder → Mitglied anlegen“ oder per Import aus Excel oder CSV („Importieren“): Bereich wählen, Vorlage laden, Datei hochladen, Spalten zuordnen, Vorschau prüfen (neu, aktualisiert, Dublette, Fehler), bei Dubletten überspringen, aktualisieren oder neu anlegen. Der Import wird ganz oder gar nicht übernommen und lässt sich 24 Stunden lang rückgängig machen. Austritte beenden Mannschaftszugehörigkeiten und sperren den App-Zugang. In der Mitgliederliste filterst du nach Rolle, Trainerteam, individuellen Rechten oder fehlendem App-Zugang.": "Individualmente en «Socios → Crear socio» o mediante importación desde Excel o CSV («Importar»): elige el área, descarga la plantilla, sube el archivo, asigna columnas, revisa la vista previa (nuevo, actualizado, duplicado, error) y, en caso de duplicados, omite, actualiza o crea de nuevo. La importación se aplica por completo o no se aplica, y se puede deshacer durante 24 horas. Las bajas finalizan las pertenencias a equipos y bloquean el acceso a la app. En la lista de socios filtras por rol, cuerpo técnico, derechos individuales o falta de acceso a la app.",
