  "Erinnerung, Bezahlinfos und Kassenprüfung?": "¿Recordatorio, datos de pago y auditoría de caja?",
  "Erinnerungen": "Recordatorios",
  "Erinnerungen an offene Beträge verschickst du per Knopf oder lässt sie monatlich automatisch laufen (Einstellungen). Unter „Bezahlinfos & Einstellungen“ hinterlegst du IBAN und PayPal und bestimmst, ob alle die Beträge aller Beteiligten sehen (Standard: jeder nur die eigenen; Kassenstand, Einnahmen und Ausgaben sieht immer die ganze Mannschaft). „Kassenprüfung“ hält den Stand mit Prüfer fest. Berichte gibt es als Excel und PDF.": "Los recordatorios de importes pendientes los envías con un botón o los dejas correr automáticamente cada mes (Ajustes). En «Datos de pago y ajustes» guardas el IBAN y PayPal y decides si todos ven los importes de todos los participantes (por defecto: cada uno solo los suyos; el saldo de caja, los ingresos y los gastos los ve siempre todo el equipo). «Auditoría de caja» registra el estado con el auditor. Los informes están disponibles en Excel y PDF.",
