  "Es erscheint oben in der App bei allen Mitgliedern. Ohne Logo zeigt die App ein Wappen mit dem Kürzel.": "Aparece arriba en la app para todos los socios. Sin logotipo, la app muestra un escudo con la abreviatura.",
  "Es fehlen {0} aktive Schiedsrichter": "Faltan {0} árbitros activos",
  "Es fehlen zugeordnete Pflichtfelder.": "Faltan campos obligatorios por asignar.",
  "Es gab nichts zu übernehmen.": "No había nada que aplicar.",
  "Es gibt {0} neue Funktionen": "Hay {0} funciones nuevas",
  "Es gibt 1 neue Funktion": "Hay 1 función nueva",
  "Es gibt bereits Kategorien.": "Ya existen categorías.",
  "Es gibt keine Einnahmekategorie für Beiträge. Lege sie in der Vereinskasse an.": "No hay categoría de ingresos para cuotas. Créala en la caja del club.",
  "Es gibt keine neuen Mitglieder zu übernehmen.": "No hay socios nuevos que aplicar.",
  "Es gibt nichts zu übernehmen.": "No hay nada que aplicar.",
  "Es gibt noch fehlerhafte Zeilen. Bitte korrigieren oder abwählen.": "Aún hay filas con errores. Corrígelas o desmárcalas.",
  "Es gibt noch keine Erwachsenen mit Login in der Mannschaft.": "Aún no hay adultos con acceso en el equipo.",
  "Es gibt noch keine Kategorien für diese Art. Lege sie unter „Einrichtung“ an.": "Aún no hay categorías para este tipo. Créalas en «Configuración».",
  "Es gibt nur einen Fulladmin – lege einen zweiten an.": "Solo hay un administrador total; crea un segundo.",
  "Es gibt zwei Wege: Unter „Ich“ stehen direkt unter deinem Profil die zwei farbigen Knöpfe „Admin-Verwaltung“ (violett) und „Vereinskasse“ (blau) – nur die, für die du Rechte hast. Außerdem steht unter „Verein“ in der Gruppe „Meine Vereinsaufgaben“ der Zugang zur „Verwaltung“ (für alle mit Verwaltungsrechten) und zur „Vereinskasse“ (für alle mit Kassenzugriff); am Desktop stehen beide dauerhaft in der Seitenleiste. Beide öffnen einen eigenen Bereich mit farbigem Kopfband und „Zur App“ oben sowie einer Leiste mit Reitern unten. Die Verwaltung hat die Reiter Übersicht, Mitglieder, Sport, Inhalte und Verein – du siehst nur, wofür du Rechte hast. In der Vereinskasse gibt es Übersicht, Buchung, Beiträge, Planung und Auswertung. Funktionen mit „Bald verfügbar“ folgen in einem späteren Update.": "Hay dos caminos: en «Yo», justo debajo de tu perfil, están los dos botones de color «Administración» (violeta) y «Caja del club» (azul), solo los de los que tienes derechos. Además, en «Club», en el grupo «Mis tareas del club», está el acceso a «Administración» (para todos con derechos de administración) y a «Caja del club» (para todos con acceso a la caja); en el ordenador, ambos están siempre en la barra lateral. Ambos abren un área propia con cabecera de color y «A la app» arriba, y una barra con pestañas abajo. La administración tiene las pestañas Resumen, Socios, Deporte, Contenidos y Club; solo ves aquello para lo que tienes derechos. La caja del club incluye Resumen, Movimientos, Cuotas, Planificación e Informes. Las funciones marcadas con «Próximamente» llegarán en una actualización posterior.",
