  "Feste Gruppen müssen nicht ständig antworten – „Automatisch zugesagt“ spart Nachfragen und zeigt trotzdem, wer fehlt. Bei Spielen ist die aktive Antwort oft sinnvoller, weil der Kader begrenzt ist.": "Los grupos fijos no tienen que responder siempre: «Confirmado automáticamente» ahorra preguntas y aun así muestra quién falta. En los partidos, la respuesta activa suele ser más útil porque la plantilla es limitada.",
