  "Ganz unten auf Start findest du den Schnellzugriff – Abkürzungen zu Seiten, die du oft brauchst. Tippe auf „Hinzufügen“, wähle die Einträge aus und speichere. „Zurücksetzen“ stellt die Voreinstellung für deine Rolle wieder her. Die Auswahl gilt auf allen deinen Geräten.": "Abajo del todo, en Inicio, encuentras el acceso rápido: atajos a las páginas que usas a menudo. Toca «Añadir», elige las entradas y guarda. «Restablecer» recupera la configuración predeterminada de tu rol. La selección vale para todos tus dispositivos.",
