  "Gelöscht – lässt sich wiederherstellen": "Eliminado: se puede restaurar",
  "Gelöschte Einträge liegen hier und lassen sich wiederherstellen. Endgültig gelöscht wird nie automatisch, sondern nur auf deinen Anstoß.": "Las entradas eliminadas están aquí y se pueden restaurar. Nunca se eliminan definitivamente de forma automática, solo por iniciativa tuya.",
  "Gelöschte Rollen": "Roles eliminados",
  "Gelöschte Rollen lassen sich wiederherstellen.": "Los roles eliminados se pueden restaurar.",
  "Gelöschte Wissensartikel, Übungen, Aufgaben, Sponsoren, Dokumente und ausgemustertes Material landen im Archiv; bei Dokumenten bleibt die Datei erhalten, bis das Archiv bereinigt wird. Das Trainerteam öffnet das Archiv seiner Mannschaft unter „Team → Archiv“ (gelöschte Aufgaben und Dokumente, wiederherstellen). Die Administration öffnet das ganze Archiv unter „Verwaltung → Abo & Kontrolle → Archiv“: Dort stellst du einen Eintrag mit „Wiederherstellen“ wieder her. Ist sein Name inzwischen vergeben, fragt dich die App nach einem neuen Namen. Endgültig gelöscht wird nie automatisch: „Bereinigen“ entfernt, was älter als die Standardfrist ist (derzeit 2 Jahre), „Archiv leeren“ löscht alles; beides nur auf deinen Anstoß und mit Bestätigung. „Archiv exportieren“ speichert alle archivierten Einträge als Datei.": "Los artículos de conocimiento, ejercicios, tareas, patrocinadores, documentos y material dado de baja que se eliminan van al archivo; en los documentos, el archivo se conserva hasta que se depura el archivo. El cuerpo técnico abre el archivo de su equipo en «Equipo → Archivo» (tareas y documentos eliminados, restaurar). La administración abre todo el archivo en «Administración → Suscripción y control → Archivo»: allí restauras una entrada con «Restaurar». Si su nombre ya está en uso, la app te pide un nombre nuevo. Nunca se elimina definitivamente de forma automática: «Depurar» quita lo que es más antiguo que el plazo estándar (actualmente 2 años), «Vaciar archivo» elimina todo; ambas solo por iniciativa tuya y con confirmación. «Exportar archivo» guarda todas las entradas archivadas como archivo.",
  "Gemeinnützig": "Sin ánimo de lucro",
  "Gemeinnützige Vereine müssen Einnahmen und Ausgaben steuerlich trennen. Ist der Verein nicht gemeinnützig, reicht eine einfachere Kategorieliste.": "Los clubes sin ánimo de lucro deben separar fiscalmente ingresos y gastos. Si el club no es de utilidad pública, basta una lista de categorías más sencilla.",
