  "Hallo! Wir nutzen Clubroof für {0}: Termine, Zu- und Absagen und alle Infos an einem Ort. Hier kommst du in die Mannschaft: {1}": "¡Hola! Usamos Clubroof para {0}: eventos, confirmaciones y cancelaciones, y toda la información en un solo lugar. Aquí entras al equipo: {1}",
  "Hält den Kassenstand von heute fest – z. B. nach der Kassenprüfung oder zum Saisonende. Der Abschluss erscheint auch im Kassenbericht. Beim Saisonwechsel geht die Kasse automatisch auf die neue Mannschaft über.": "Registra el saldo de caja de hoy, p. ej., tras la auditoría de caja o al final de la temporada. El cierre aparece también en el informe de caja. En el cambio de temporada, la caja pasa automáticamente al nuevo equipo.",
