  "Je Spiel: die Nummer wird bei jeder Aufstellung neu vergeben. Fest: eine Nummer pro Spieler für die ganze Saison.": "Por partido: el número se asigna de nuevo en cada alineación. Fijo: un número por jugador para toda la temporada.",
  "Je Sponsor": "Por patrocinador",
  "Jede Änderung setzt die Freigabe der Vorlage zurück.": "Cualquier cambio restablece la aprobación de la plantilla.",
  "Jede Kasse hat eigene Konten, Beiträge und Auswertung. Ohne Zuordnung läuft eine Abteilung über die Hauptkasse. Der Jahresabschluss gilt immer für den ganzen Verein.": "Cada caja tiene sus propias cuentas, cuotas e informes. Sin asignación, una sección pasa por la caja principal. El cierre anual vale siempre para todo el club.",
  "Jede Leitung sieht nur Daten ihrer Abteilung": "Cada dirección ve solo los datos de su sección",
  "Jede Mannschaft legt fest, bis wann Zu- und Absagen möglich sind. Der Countdown steht am Termin („Frist: Noch 2 Tage“). Danach bleibt deine Antwort sichtbar (Schloss „Frist abgelaufen“), ändern kann sie nur dein Trainerteam.": "Cada equipo define hasta cuándo se puede confirmar y cancelar. La cuenta atrás aparece en el evento («Plazo: quedan 2 días»). Después tu respuesta sigue visible (candado «Plazo terminado») y solo tu cuerpo técnico puede cambiarla.",
  "Jede Person sagt zu oder ab – der Trainer sieht, wer noch fehlt": "Cada persona confirma o cancela; el entrenador ve quién falta",
  "Jede Zeile ist grün (neu), blau (aktualisiert), gelb (Dublette) oder rot (Fehler). Abgewählte Zeilen werden nicht übernommen.": "Cada fila es verde (nueva), azul (actualizada), amarilla (duplicado) o roja (error). Las filas desmarcadas no se aplican.",
  "Jeder Spieler behält seine Nummer; sie erscheint im Kader und in der Aufstellung.": "Cada jugador mantiene su número; aparece en la plantilla y en la alineación.",
  "Jeder Spieler der Startelf braucht einen Platz der Formation.": "Cada jugador del once inicial necesita una posición de la formación.",
  "Jedes Feld kann nur einer Spalte zugeordnet werden.": "Cada campo solo se puede asignar a una columna.",
  "Jedes Mitglied reicht unter „Verein → Auslage einreichen“ Kosten mit Beleg (Foto) oder Fahrtkosten ein – bei Fahrtkosten rechnet die App aus den Kilometern (30 Cent je km). Der Kassenwart sieht die Auslagen unter „Vereinskasse → Buchung → Auslagen“, genehmigt oder lehnt mit Begründung ab und erstattet: Dabei entsteht eine Ausgabe im Kassenbuch. Du bekommst zu jedem Schritt eine Benachrichtigung. Eine erstattete Auslage kann nicht storniert werden.": "Cada socio presenta en «Club → Presentar gasto adelantado» costes con justificante (foto) o gastos de viaje; en los gastos de viaje la app calcula a partir de los kilómetros (30 céntimos por km). El tesorero ve los gastos adelantados en «Caja del club → Movimientos → Gastos adelantados», los aprueba o rechaza con motivo y los reembolsa: con ello se genera un gasto en el libro de caja. Recibes una notificación en cada paso. Un gasto adelantado reembolsado no se puede anular.",
  "Jetzt einrichten": "Configurar ahora",
