  "Kassenprüfer": "Auditor de caja",
  "Kassenprüfer beginnen unter „Vereinskasse → Auswertung → Kassenprüfung“ eine Prüfung für ein Jahr – für den ganzen Verein oder nur für ihre Kasse. Die App zieht auf Wunsch zufällige Stichproben; jede Buchung wird abgehakt oder mit Begründung beanstandet, den Beleg siehst du direkt. Dazu kommen freie Vermerke. Sind alle Stichproben erledigt, gibst du den Prüfbericht mit deinem Ergebnis ab; danach ist er nicht mehr änderbar und dient als Grundlage der Entlastung. Die Kassenführung sieht abgegebene Berichte (auch als PDF oder CSV). Prüfer buchen nicht, der Kassenwart prüft nicht.": "Los auditores de caja inician en «Caja del club → Informes → Auditoría de caja» una auditoría de un año, para todo el club o solo para su caja. La app extrae, si lo deseas, muestras aleatorias; cada movimiento se marca como revisado o se le ponen reparos con motivo, y ves el justificante directamente. Además hay notas libres. Cuando todas las muestras están resueltas, entregas el informe de auditoría con tu resultado; después ya no se puede modificar y sirve de base para la aprobación de la gestión. La gestión de caja ve los informes entregados (también como PDF o CSV). Los auditores no registran movimientos; el tesorero no audita.",
  "Kassenprüfung": "Auditoría de caja",
