  "Kassenstand, Einnahmen und Ausgaben sieht immer die ganze Mannschaft. Die Beträge der einzelnen Personen zeigst du nur, wenn ihr das wollt – sonst sieht jeder nur die eigenen.": "El saldo de caja, los ingresos y los gastos los ve siempre todo el equipo. Los importes de cada persona solo los muestras si lo queréis; si no, cada uno ve solo los suyos.",
