  "Kurzfristige Absagen und dringende Vereinsnews erreichen dich unabhängig von diesen Einstellungen – auch in der Ruhezeit.": "Las cancelaciones de última hora y las noticias urgentes del club te llegan independientemente de estos ajustes, también en el horario de descanso.",
