  "Lade Daten als Excel- oder CSV-Datei herunter. Du siehst nur, wofür du Rechte hast; jeder Export wird im Protokoll des Vereins festgehalten.": "Descarga datos como archivo Excel o CSV. Solo ves aquello para lo que tienes derechos; cada exportación queda registrada en el registro del club.",
  "Lade den Kontoauszug als CSV-Datei deiner Bank hoch. Erkannt werden Buchungstag, Betrag, Name und Verwendungszweck. Zugeordnet wird per Mitgliedsnummer oder Name, wenn der Betrag genau zu einer offenen Forderung passt. Du siehst alles vorher.": "Sube el extracto bancario como archivo CSV de tu banco. Se reconocen fecha, importe, nombre y concepto. Se asigna por número de socio o nombre si el importe coincide exactamente con un cobro pendiente. Lo ves todo de antemano.",
  "Lade den Spielplan als CSV-Datei aus dem DFBnet (Meisterschaft › Vereinsspielplan bzw. Mannschaftsspielplan › Export). Du siehst zuerst eine Vorschau – übernommen wird erst nach deiner Bestätigung. Ein erneuter Import aktualisiert bestehende Spiele, statt sie doppelt anzulegen.": "Sube el calendario como archivo CSV de DFBnet (Campeonato › Calendario del club o Calendario del equipo › Exportar). Primero ves una vista previa; no se aplica hasta que lo confirmes. Una nueva importación actualiza los partidos existentes en lugar de duplicarlos.",
