  "Lege das Mitglied an und ordne es danach einer Mannschaft zu. Den App-Zugang erhält es später über eine Einladung.": "Crea el socio y luego asígnalo a un equipo. El acceso a la app lo recibirá más tarde mediante una invitación.",
  "Lege Strafen und Beträge fest. Vergebene Strafen landen auf dem Konto der Person; eine spätere Änderung gilt nur für neue Strafen.": "Define multas e importes. Las multas puestas se cargan en la cuenta de la persona; un cambio posterior solo vale para multas nuevas.",
