  "Mannschaften melden Spielerbedarf oder bieten Spieler an. Abgestellt wird immer durch den Trainer der abgebenden Mannschaft – andere sehen nur, wie viele Spieler verfügbar sind.": "Los equipos comunican necesidad de jugadores u ofrecen jugadores. La cesión la hace siempre el entrenador del equipo de origen; los demás solo ven cuántos jugadores hay disponibles.",
