  "Meldungen kommen danach gesammelt an.": "Los avisos llegan después de forma agrupada.",
  "Mi": "Mi",
  "Mich": "A mí",
  "Minderjährig ohne Elternteil und ohne E-Mail – später zuordnen.": "Menor sin padre/madre ni correo electrónico; asignar más tarde.",
  "Mindestens 10 Zeichen – am besten ein kurzer Satz.": "Al menos 10 caracteres; lo mejor es una frase corta.",
  "Mindestens 10 Zeichen. Eine Wortfolge oder ein Satz ist sicherer und leichter zu merken als ein kurzes Passwort mit Sonderzeichen.": "Al menos 10 caracteres. Una secuencia de palabras o una frase es más segura y fácil de recordar que una contraseña corta con caracteres especiales.",
  "Mindestens eine importierte Person hat schon ein Konto. Der Import lässt sich nicht mehr rückgängig machen.": "Al menos una persona importada ya tiene una cuenta. La importación ya no se puede deshacer.",
  "Mindestens zwei Buchstaben eingeben.": "Introduce al menos dos letras.",
  "Mini-Forum": "Miniforo",
  "Mit Ablaufdatum": "Con fecha de caducidad",
  "Mit App-Zugang": "Con acceso a la app",
  "Mit dem Start wird {0} zur laufenden Saison. Mannschaftskassen, Mannschaftsdokumente und künftige Termine gehen auf die neuen Mannschaften über. Zuordnungen und Aufgaben der alten Saison enden. Das lässt sich nicht rückgängig machen.": "Al iniciar, {0} pasa a ser la temporada en curso. Las cajas de equipo, los documentos de equipo y los eventos futuros pasan a los nuevos equipos. Las asignaciones y tareas de la temporada anterior terminan. Esta acción no se puede deshacer.",
  "Mit den Pfeilen verschiebst du das Datum um einen Tag. Tippst du auf das Datum selbst, öffnet sich ein Kalender: Wische oder tippe auf die Pfeile, um den Monat zu wechseln, tippe auf einen Tag zum Auswählen oder wähle „Heute“. Nicht erlaubte Tage sind ausgegraut.": "Con las flechas desplazas la fecha un día. Si tocas la propia fecha, se abre un calendario: desliza o toca las flechas para cambiar de mes, toca un día para seleccionarlo o elige «Hoy». Los días no permitidos aparecen en gris.",
  "Mit den Schreibweisen aus dem DFBnet ordnet der Spielplan-Import die Spiele richtig zu.": "Con las grafías de DFBnet, la importación del calendario asigna correctamente los partidos.",
  "Mit der Anschrift füllt Clubroof Spendenbescheinigungen aus; die Zeitzone bestimmt Fristen und Terminzeiten.": "Con la dirección, Clubroof rellena los certificados de donación; la zona horaria determina plazos y horas de los eventos.",
  "Mit der Zwei-Faktor-Anmeldung braucht jede neue Anmeldung zusätzlich einen Code. Für das Administrationskonto empfehlen wir sie.": "Con la autenticación en dos pasos, cada nuevo inicio de sesión necesita además un código. La recomendamos para la cuenta de administración.",
  "Mit dieser E-Mail-Adresse gibt es bereits ein Konto. Bitte melde dich an oder nutze „Passwort vergessen“.": "Ya existe una cuenta con este correo electrónico. Inicia sesión o usa «Olvidé mi contraseña».",
  "Mit Einladungslink oder Einladungscode (auch per QR-Code scannen) trittst du deinem Verein bei – der Verein wird danach auf diesem Gerät gemerkt. Hast du schon ein Konto, melde dich mit E-Mail und Passwort an („Zeigen“ macht das Passwort sichtbar). Einen neuen Verein richtest du mit dem Einrichtungscode (Format CR-XXXX-XXXX) ein, den du von Clubroof nach Zahlungseingang erhältst; er gilt einmal.": "Con el enlace o el código de invitación (también escaneando un código QR) te unes a tu club; después el club se recuerda en este dispositivo. Si ya tienes una cuenta, inicia sesión con correo electrónico y contraseña («Mostrar» hace visible la contraseña). Un club nuevo se configura con el código de configuración (formato CR-XXXX-XXXX) que recibes de Clubroof tras recibirse el pago; es de un solo uso.",
  "Mit Face ID oder Fingerabdruck entsperren": "Desbloquear con Face ID o huella",
  "Mit festen Trainingszeiten stehen die Termine sofort im Kalender, und Zu- und Absagen funktionieren ab dem ersten Tag.": "Con horarios de entrenamiento fijos, los eventos aparecen enseguida en el calendario y las confirmaciones y cancelaciones funcionan desde el primer día.",
  "Mit Namen": "Con nombres",
  "Mit PayPal bezahlen": "Pagar con PayPal",
