  "Mitglieder melden Zahlungen in ihrem Konto. Du siehst sie in der Kassenverwaltung unter „Zahlungsmeldungen“ und bestätigst mit „Eingegangen“ – dann wird die Einzahlung gebucht – oder „Nicht gefunden“.": "Los socios comunican pagos en su cuenta. Los ves en la gestión de caja, en «Avisos de pago», y confirmas con «Recibido» (entonces se registra el pago recibido) o «No encontrado».",
