  "Nach Beginn eines Termins hakst du ab, wer wirklich da war (vorausgewählt sind die Zusagen). Danach zählt für Trainingsquote und Statistik die Anwesenheit statt der Zusage. Auf Start erinnert dich ein Hinweis an Trainings der letzten Woche.": "Tras el inicio de un evento marcas quién estuvo realmente (las confirmaciones vienen preseleccionadas). Después, para la tasa de entrenamiento y las estadísticas cuenta la asistencia en lugar de la confirmación. En Inicio, un aviso te recuerda los entrenamientos de la última semana.",
