  "Name, Kontaktdaten, Mannschaftszugehörigkeit, Zu- und Absagen sowie – nur für Berechtigte – Kassendaten. Gründe für Abwesenheiten sind nur für Trainer und Verantwortliche sichtbar.": "Nombre, datos de contacto, pertenencia a equipos, confirmaciones y cancelaciones y, solo para personas autorizadas, datos de caja. Los motivos de ausencia solo son visibles para entrenadores y responsables.",
