  "Nein": "No",
  "Nein. In der Ruhezeit (22 bis 7 Uhr) gibt es keine Push-Nachrichten außer bei dringenden Meldungen. Alles andere wartet bis zum Morgen.": "No. En el horario de descanso (de 22 a 7 h) no hay notificaciones push, salvo avisos urgentes. Todo lo demás espera hasta la mañana.",
  "Nein. Trage eine Abwesenheit ein (Urlaub, Verletzt, Krank, Sonstiges). Alle betroffenen Termine werden automatisch abgesagt, das Trainerteam sieht es sofort. Löschst du die Abwesenheit, werden die automatischen Absagen zurückgenommen.": "No. Registra una ausencia (vacaciones, lesión, enfermedad, otros). Todos los eventos afectados se cancelan automáticamente y el cuerpo técnico lo ve al instante. Si eliminas la ausencia, se revocan las cancelaciones automáticas.",
