  "Nummern je Spiel oder fest vergeben": "Asignar números por partido o de forma fija",
  "Nur Admins: Verwaltung › Rollen und Rechte › „Neue Rolle“. Du gibst Name, Beschreibung und den Geltungsbereich (Verein, Abteilung, Mannschaft) an und wählst die Rechte in Klartext; mit „Start als Kopie von“ übernimmst du eine vorhandene Rolle. Sensible Rechte tragen ein Schloss. Vereinsweite Rechte (Verein, Vereinskasse, Mitglieder) gibt es nur in vereinsweiten Rollen, und du kannst nur Rechte vergeben, die du selbst hast. Standardrollen sind geschützt – dort gibt es „Kopie anpassen“. Gelöschte Rollen lassen sich wiederherstellen; Personen stellst du beim Löschen auf eine andere Rolle um. In der Übersicht zeigen die Reiter Rollen, Personen und Matrix den Stand; bei einer Person zeigt „Was darf diese Person?“ jedes Recht mit seiner Quelle.": "Solo administradores: Administración › Roles y derechos › «Nuevo rol». Indicas nombre, descripción y ámbito (club, sección, equipo) y eliges los derechos en lenguaje claro; con «Empezar como copia de» partes de un rol existente. Los derechos sensibles llevan un candado. Los derechos de todo el club (club, caja del club, socios) solo existen en roles de todo el club, y solo puedes asignar derechos que tú mismo tienes. Los roles estándar están protegidos; allí hay «Adaptar copia». Los roles eliminados se pueden restaurar; al eliminar, pasas a las personas a otro rol. En el resumen, las pestañas Roles, Personas y Matriz muestran la situación; en una persona, «¿Qué puede hacer esta persona?» muestra cada derecho con su origen.",
  "Nur Anzahl": "Solo cantidad",
  "Nur App": "Solo app",
  "Nur ausgewählte": "Solo seleccionados",
  "Nur das Trainerteam sieht die Gründe; Eltern sehen die Gründe ihres Kindes.": "Solo el cuerpo técnico ve los motivos; los padres ven los motivos de su hijo.",
  "Nur das Trainerteam sieht Kontaktdaten": "Solo el cuerpo técnico ve los datos de contacto",
  "Nur das Trainerteam sieht Zahlen und Namen; Spieler und Eltern sehen nur die eigene Antwort.": "Solo el cuerpo técnico ve cifras y nombres; jugadores y padres ven solo su propia respuesta.",
  "Nur das Trainerteam sieht, wer da war.": "Solo el cuerpo técnico ve quién estuvo.",
  "Nur der Fahrer kann das Angebot zurückziehen.": "Solo el conductor puede retirar la oferta.",
  "Nur die Startelf hat Plätze.": "Solo el once inicial tiene posiciones.",
  "Nur die Verwaltung": "Solo la administración",
