  "So funktioniert die App. Tippe auf eine Frage, um die Antwort zu lesen – oder suche nach einem Stichwort. Fragen zum Verein selbst beantworten dir die Ansprechpartner.": "Así funciona la app. Toca una pregunta para leer la respuesta o busca una palabra clave. Las preguntas sobre el propio club te las responden las personas de contacto.",
