  "So steht es in der Werbung.": "Así aparece en la publicidad.",
  "So wenig wie nötig: Gründe für Absagen und Abwesenheiten sehen nur das Trainerteam und du. Kontaktdaten sehen nur die Personen, die du freigibst. Eltern sehen die Daten ihrer Kinder. Trainingsbeteiligung und Kassenstand sieht die eigene Mannschaft.": "Lo mínimo necesario: los motivos de cancelaciones y ausencias solo los ven el cuerpo técnico y tú. Los datos de contacto solo los ven las personas que tú autorizas. Los padres ven los datos de sus hijos. La participación en entrenamientos y el saldo de caja los ve el propio equipo.",
