  "Sportgeräte und Material": "Material deportivo y equipamiento",
  "Sportliche Leitung": "Dirección deportiva",
  "Sportliche Leitung, Jugendleitung und Vorstand sehen im Reiter „Team“ eine Übersicht über die Abteilungen (Senioren, Frauen, Jugend) – ohne Zugriff in die einzelnen Mannschaften. Oben stehen die Kennzahlen, darunter eine Karte je Mannschaft mit Kader, Trainerteam, Trainingsbeteiligung der letzten 4 Wochen und dem nächsten Spiel. Die Ampel gilt nur für die Trainingsbeteiligung: gut ab 65 %, mittel 50–64 %, niedrig darunter; bei weniger als 3 erfassten Einheiten steht „zu wenig Daten“. Wer auch selbst in einer Mannschaft ist, schaltet oben zwischen „Meine Mannschaft“ und „Übersicht“ um.": "La dirección deportiva, la dirección juvenil y la junta directiva ven en la pestaña «Equipo» un resumen de las secciones (Senior, Femenino, Juvenil), sin acceso a los equipos individuales. Arriba están los indicadores y debajo una tarjeta por equipo con plantilla, cuerpo técnico, participación en entrenamientos de las últimas 4 semanas y el próximo partido. El semáforo solo vale para la participación en entrenamientos: bueno desde 65 %, medio 50–64 %, bajo por debajo; con menos de 3 sesiones registradas aparece «datos insuficientes». Quien además esté en un equipo cambia arriba entre «Mi equipo» y «Resumen».",
