  "Strafen und ihre Beträge legen Trainerteam und Kassenwart im Strafenkatalog fest („Team → Strafenkatalog“). Wurde dir eine Strafe vergeben, steht sie als offener Betrag auf deinem Konto und du bekommst eine Benachrichtigung.": "Las multas y sus importes los fijan el cuerpo técnico y el tesorero en el catálogo de multas («Equipo → Catálogo de multas»). Si se te pone una multa, aparece como importe pendiente en tu cuenta y recibes una notificación.",
