  "Tipp: Ort in der Karten-App suchen, „Teilen“ wählen und den Link hier einfügen. Ohne Link nutzt „Route“ die eingetragene Adresse.": "Consejo: busca el lugar en la app de mapas, elige «Compartir» y pega aquí el enlace. Sin enlace, «Ruta» usa la dirección registrada.",
  "Tippe auf der Anmeldeseite auf „Passwort vergessen?“. Du bekommst einen Link per E-Mail, mit dem du ein neues Passwort festlegst. Im Konto kannst du es jederzeit ändern.": "En la página de inicio de sesión toca «¿Olvidaste tu contraseña?». Recibirás un enlace por correo electrónico para establecer una contraseña nueva. En la cuenta puedes cambiarla en cualquier momento.",
  "Tippe auf die Uhrzeit: Es öffnet sich ein Fenster mit zwei Drehwalzen wie bei einem Wecker – links die Stunde, rechts die Minute (in 5er-Schritten). Wische oder scrolle, bis die richtige Zeit in der Mitte steht, und tippe auf „Übernehmen“. Beim Anlegen eines Termins wählst du Beginn und Ende; die Dauer zeigt die App darunter.": "Toca la hora: se abre una ventana con dos ruedas como en un despertador: a la izquierda la hora, a la derecha los minutos (de 5 en 5). Desliza o desplázate hasta que la hora correcta quede en el centro y toca «Aplicar». Al crear un evento eliges inicio y fin; la app muestra la duración debajo.",
  "Tippe auf einen Spieler, um seine Rückmeldung zu korrigieren.": "Toca un jugador para corregir su respuesta.",
  "Tippe im Termin bei „Teilnehmer“ auf eine Person und wähle Zusage, Unsicher oder Absage. Das geht auch nach Ablauf der Frist (bis eine Woche nach Beginn).": "En el evento, en «Participantes», toca una persona y elige Confirmar, Dudoso o Cancelar. Esto se puede hacer también después del plazo (hasta una semana tras el inicio).",
  "Tippe in „Mein Konto“ auf „Bezahlen / Zahlung melden“. Du siehst die Bezahlinfos der Mannschaft (IBAN zum Kopieren, PayPal, bar). Nach dem Bezahlen tippst du „Ich habe bezahlt“. Sobald die Kasse den Eingang bestätigt hat, ist dein Konto ausgeglichen.": "En «Mi cuenta» toca «Pagar / Avisar de un pago». Verás los datos de pago del equipo (IBAN para copiar, PayPal, efectivo). Tras pagar, toca «He pagado». En cuanto la caja confirme la recepción, tu cuenta queda saldada.",
  "Tippe oben rechts auf die Lupe und gib mindestens zwei Buchstaben ein. Du findest Termine, Mitglieder, News und Mannschaften. Personen siehst du nur, wenn du auch sonst ihr Profil sehen darfst (z. B. aus deiner Mannschaft oder deine Kinder).": "Toca la lupa arriba a la derecha e introduce al menos dos letras. Encontrarás eventos, socios, noticias y equipos. Solo ves personas si también puedes ver su perfil en otros contextos (p. ej., de tu equipo o tus hijos).",
