  "Trage ein, wann du oder deine Kinder nicht verfügbar bist. Betroffene Termine werden automatisch abgesagt, dein Trainerteam sieht es sofort.": "Indica cuándo no estás disponible tú o tus hijos. Los eventos afectados se cancelan automáticamente y tu cuerpo técnico lo ve al instante.",
