  "Über das Schild-Symbol oben rechts oder „Ich → Admin-Verwaltung“ oder „Verein → Meine Vereinsaufgaben → Verwaltung“. Mit „Zur App“ kehrst du zur normalen App zurück. Unten wechselst du zwischen Übersicht, Mitgliedern, Teams, Festen und News.": "Mediante el icono de escudo arriba a la derecha, «Yo → Administración» o «Club → Mis tareas del club → Administración». Con «A la app» vuelves a la app normal. Abajo cambias entre Resumen, Socios, Equipos, Fiestas y Noticias.",
