  "Umlage: Gesamtbetrag auf gewählte Personen aufteilen oder festen Betrag je Person fordern. Beiträge: z. B. 5 € monatlich, die App bucht sie allen Spielern zum Fälligkeitstag. Getränke: Preis festlegen und je Person Striche zählen. Alle Betroffenen werden benachrichtigt.": "Derrama: repartir el importe total entre las personas elegidas o cobrar un importe fijo por persona. Cuotas: p. ej., 5 € al mes; la app las carga a todos los jugadores en la fecha de vencimiento. Bebidas: fijar precio y contar marcas por persona. Se avisa a todos los afectados.",
