  "Was soll der ganze Verein nutzen können? Empfohlenes ist vorausgewählt. „Vereinskasse“ ist nur der Schalter – eingerichtet wird sie danach in einem eigenen Assistenten.": "¿Qué debe poder usar todo el club? Lo recomendado viene preseleccionado. «Caja del club» es solo el interruptor; se configura después en un asistente propio.",
