  "Welche Beitragsarten gibt es? Mit Vorschlägen starten und Beträge anpassen.": "¿Qué tipos de cuota hay? Empieza con sugerencias y ajusta los importes.",
  "Welche Daten habt ihr schon? Die Importe laufen nach der Einrichtung, jeweils mit Vorlage, Spaltenzuordnung und Vorschau. Excel-Dateien mit mehreren Blättern gehen auch – du wählst das Blatt aus.": "¿Qué datos tenéis ya? Las importaciones se hacen tras la configuración, siempre con plantilla, asignación de columnas y vista previa. También sirven archivos Excel con varias hojas: eliges la hoja.",
  "Welche Daten wir verarbeiten": "Qué datos tratamos",
  "Welche Daten wir verarbeiten und warum": "Qué datos tratamos y por qué",
  "Welche Kasse?": "¿Qué caja?",
  "Welche Konten und Kassen gibt es?": "¿Qué cuentas y cajas hay?",
  "Welche Meldungen bekomme ich und wie stelle ich sie ein?": "¿Qué avisos recibo y cómo los configuro?",
  "Welche Vorlage passt?": "¿Qué plantilla encaja?",
  "Welcher Untergrund?": "¿Qué superficie?",
  "Welches Mitglied welche Beitragsart zahlt (ab wann, optional mit abweichendem Betrag). Mitglieder werden über Mitgliedsnummer oder Namen erkannt.": "Qué socio paga qué tipo de cuota (desde cuándo, opcionalmente con importe distinto). Los socios se reconocen por número de socio o nombre.",
  "Wenige Themen, die nach Ablauf schließen – für Absprachen, Ideen und Rückmeldungen. Bitte freundlich bleiben; das Moderationsteam blendet Unpassendes aus.": "Pocos temas que se cierran al terminar su plazo, para acuerdos, ideas y comentarios. Sé amable; el equipo de moderación oculta lo inadecuado.",
  "Wenige, moderierte Diskussionsthemen": "Pocos temas de debate moderados",
  "Wenn dein Verein das Sponsoren-Modul nutzt, zeigt ein kleines Wischelement auf Start, im Team-Reiter und im Verein-Reiter bis zu drei Sponsoren, die der Verein als Werbung freigegeben hat. Es ist immer als „Anzeige“ gekennzeichnet und wechselt alle paar Sekunden von selbst; du kannst auch wischen. Ein Tipp öffnet die Seite des Sponsors. Alle Sponsoren findest du unter „Verein → Sponsoren“. Die App wertet nicht aus, wer was ansieht oder antippt. Manche Sponsoren stellt der Verein so ein, dass Jugendspieler sie nicht sehen.": "Si tu club usa el módulo de patrocinadores, un pequeño elemento deslizable en Inicio, en la pestaña Equipo y en la pestaña Club muestra hasta tres patrocinadores que el club ha habilitado como publicidad. Siempre está marcado como «Anuncio» y cambia solo cada pocos segundos; también puedes deslizar. Un toque abre la página del patrocinador. Todos los patrocinadores los encuentras en «Club → Patrocinadores». La app no analiza quién ve o toca qué. Algunos patrocinadores los configura el club para que los jugadores juveniles no los vean.",
  "Wenn deine Rückmeldung (oder die deines Kindes) noch fehlt – so lange vor der Frist:": "Si aún falta tu respuesta (o la de tu hijo): con esta antelación respecto al plazo:",
  "Wenn du das nicht warst, ignoriere diese E-Mail – dein Passwort bleibt unverändert.": "Si no has sido tú, ignora este correo; tu contraseña no cambia.",
  "Wenn du dich nicht angemeldet hast, ändere bitte dein Passwort.": "Si no has iniciado sesión tú, cambia tu contraseña.",
  "Wenn eine Mannschaft für ein Spiel Spieler braucht, meldet das Trainerteam einen Bedarf. Andere Mannschaften können Spieler abstellen. Du siehst dann den Einsatz im Termin als „Gastspieler“.": "Cuando un equipo necesita jugadores para un partido, el cuerpo técnico comunica una necesidad. Otros equipos pueden ceder jugadores. Entonces ves la participación en el evento como «Jugador invitado».",
  "Wenn eine Zu- oder Absage noch fehlt": "Cuando aún falta una confirmación o cancelación",
  "Wenn eingeschaltet, brauchen alle mit Verwaltungsrechten (Vorstand, Admins, Jugendleitung …) die 2-Faktor-Anmeldung, bevor sie Mitgliederdaten bearbeiten können.": "Si está activado, todos los que tienen derechos de administración (junta directiva, administradores, dirección juvenil…) necesitan la autenticación en dos pasos antes de poder editar datos de socios.",
